const db = require('better-sqlite3')('world.db', {readonly: true});

// Get cart
const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id = 'user_fbab7801'\").get();
console.log('=== CART ===');
console.log(JSON.stringify(cart, null, 2));

// Get cart items
const items = db.prepare(\"SELECT * FROM cart_items WHERE customer_id = 'user_fbab7801'\").all();
console.log('\n=== CART ITEMS ===');
items.forEach(i => console.log(JSON.stringify(i, null, 2)));

// Get product details for each item
const productIds = items.map(i => i.product_id);
const uniqueIds = [...new Set(productIds)];
console.log('\n=== PRODUCTS ===');
uniqueIds.forEach(pid => {
  const p = db.prepare('SELECT * FROM products WHERE product_id = ?').get(pid);
  if (p) {
    // Parse JSON fields
    const parsed = {...p};
    try { parsed.specs = JSON.parse(p.specs_json || '{}'); } catch(e) {}
    console.log(JSON.stringify({
      product_id: p.product_id,
      name: p.name,
      brand: p.brand,
      category: p.category,
      price: p.price,
      in_stock: p.in_stock,
      stock_quantity: p.stock_quantity,
      gift_wrap_available: p.gift_wrap_available,
      shipping_days: p.shipping_days,
      description: p.description,
    }, null, 2));
  }
});

// Get customer account
const user = db.prepare(\"SELECT * FROM users WHERE user_id = 'user_fbab7801'\").get();
console.log('\n=== CUSTOMER ===');
if (user) {
  console.log(JSON.stringify({
    user_id: user.user_id, name: user.name, email: user.email,
    loyalty_tier: user.loyalty_tier, loyalty_points: user.loyalty_points
  }, null, 2));
} else {
  console.log('Not found in users table');
}

db.close();
